def find_topmost_carpet(n, carpets, point):
    def is_inside_carpet(carpet, point):
        (x1, y1, x2, y2) = carpet
        (x, y) = point
        return x1 <= x <= x2 and y1 <= y <= y2

    def is_topmost_carpet(carpet, other_carpets, point):
        if not is_inside_carpet(carpet, point):
            return False
        for other_carpet in other_carpets:
            if is_inside_carpet(other_carpet, point) and other_carpet[2] >= carpet[2] and other_carpet[3] >= carpet[3]:
                return False
        return True

    topmost_carpet = None
    for carpet in carpets:
        if is_topmost_carpet(carpet, carpets, point):
            topmost_carpet = carpet
            break

    return topmost_carpet[0] if topmost_carpet else -1
```
