def max_product(num_str: str, N: int, K: int) -> int:
    if K == 0 or N == 1:
        return int(num_str)
    elif K == N - 1:
        return int(num_str) * (N - 1)
    else:
        max_prod = 0
        for i in range(N - K, N):
            prod = int(num_str[0:i]) * int(num_str[i:])
            if prod > max_prod:
                max_prod = prod
        return max_prod
