def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms: List[str] = []
    for i, c in enumerate(coeffs):
        if c == 0:
            continue
        term: str = ''
        if c > 0:
            term += '+'
        elif c < 0:
            term += '-'
        abs_c = abs(c)
        if abs_c != 1 or term != '-':
            term += str(abs_c)
        if i > 0:
            term += 'x'
            if i > 1:
                term += '^' + str(i)
        terms.append(term)
    return ''.join(terms)
