def count_sequences(n: int, last: int, memo: dict) -> int:
    if n == last:
        return 1
    if last in memo:
        return memo[last]
    count = 0
    for i in range(1, int(last / 2) + 1):
        if last + i > n:
            count += count_sequences(n, last + i, memo)
    memo[last] = count
    return count
