def min_remaining_space(V, n, volumes):
    # Initialize the dp table with 0s
    dp = [0] * (n + 1)

    # Loop through the items
    for i in range(1, n + 1):
        # Find the maximum occupied volume by considering all subsets
        # of the items from 0 to i (inclusive)
        for j in range(i):
            dp[i] = max(dp[i], dp[j] + (V - volumes[j]))

    # Return the minimum remaining space
    return (V - dp[n])
```

